// ============================================================================
// [ANTI-PATTERN / BUGGY] Hai Lỗi Kinh Điển Làm Nổ Tung RAM Khi Dùng Redis Streams
// 1. XADD không có MAXLEN / MINID -> Nhật ký phình vô hạn theo thời gian
// 2. XREADGROUP quên gọi XACK -> Bảng PEL giữ rò rỉ bộ nhớ vĩnh viễn!
// ============================================================================

import Redis from "ioredis";

export async function publishAndConsumeStreamBuggy(redis: Redis): Promise<void> {
  // LỖI 1: Không truyền MAXLEN ~ N!
  // Khác với List (RPOP lấy ra là mất), XADD là nhật ký chỉ-ghi-thêm (Append-Only Log).
  // Sau 1 tuần chạy 5,000 msg/s, luồng này nuốt trọn hàng chục GB RAM!
  await redis.xadd(
    "stream:telemetry",
    "*",
    "device",
    "sensor_88",
    "payload",
    JSON.stringify({ temp: 36.7, ts: Date.now() }),
  );

  // LỖI 2: Đọc thông qua Consumer Group nhưng KHÔNG BAO GIỜ gọi redis.xack(...)!
  const records = await redis.xreadgroup(
    "GROUP",
    "cg_analytics",
    "worker_leak_1",
    "COUNT",
    50,
    "BLOCK",
    1000,
    "STREAMS",
    "stream:telemetry",
    ">",
  );

  if (records) {
    for (const [, messages] of records as Array<[string, Array<[string, string[]]>]>) {
      for (const [id] of messages) {
        console.log("Processed telemetry id:", id);
        // THIẾU: await redis.xack("stream:telemetry", "cg_analytics", id);
        // Mỗi bản ghi chưa XACK sẽ treo vĩnh viễn trong cấu trúc Radix Tree của PEL!
      }
    }
  }
}

// ============================================================================
// Cache-Aside Chuẩn Thực Chiến: Chống Bão Cache Stampede (Singleflight) + TTL Jitter
// Đảm bảo khi khóa nóng hết hạn, chỉ ĐÚNG 1 truy vấn chạm xuống PostgreSQL!
// ============================================================================

import Redis from "ioredis";

// Bản đồ gộp các Promise đang bay ngay trong tiến trình Node.js (In-Process Coalescing)
const inflightRequests = new Map<string, Promise<unknown>>();
const NULL_SENTINEL = "__CACHE_NULL__";

function computeJitteredTtl(baseSeconds: number, jitterRatio = 0.15): number {
  const delta = Math.floor(baseSeconds * jitterRatio * Math.random());
  return baseSeconds + delta; // Phân tán thời điểm hết hạn chống Cache Avalanche!
}

export async function getOrLoadWithShield<T>(
  redis: Redis,
  cacheKey: string,
  baseTtlSec: number,
  dbLoader: () => Promise<T | null>,
): Promise<T | null> {
  const cached = await redis.get(cacheKey);
  if (cached === NULL_SENTINEL) return null;
  if (cached !== null) return JSON.parse(cached) as T;

  const existingPromise = inflightRequests.get(cacheKey) as Promise<T | null> | undefined;
  if (existingPromise) {
    return existingPromise; // 999 request đến sau dùng chung kết quả của request đầu tiên!
  }

  const loadPromise = (async (): Promise<T | null> => {
    try {
      const fresh = await dbLoader();
      if (fresh === null) {
        // Cache tạm giá trị rỗng 60s để chặn đứng tấn công Cache Penetration
        await redis.set(cacheKey, NULL_SENTINEL, "EX", 60);
        return null;
      }
      await redis.set(cacheKey, JSON.stringify(fresh), "EX", computeJitteredTtl(baseTtlSec));
      return fresh;
    } finally {
      inflightRequests.delete(cacheKey);
    }
  })();

  inflightRequests.set(cacheKey, loadPromise);
  return loadPromise;
}

caching/bloom-shield-penetration-guard.t:
// ============================================================================
// Lá Chắn Kép Chống Tấn Công Xuyên Thủng Cache (Cache Penetration Guard)
// Lớp 1: Redis 8 Native Bloom Filter (BF.EXISTS) · Lớp 2: Short-TTL Null Sentinel
// ============================================================================

import Redis from "ioredis";

const BLOOM_KEY = "bf:catalog:product_ids";
const NULL_MARKER = "__NOT_FOUND__";

export interface ProductRecord {
  id: string;
  name: string;
  priceVnd: number;
}

export async function getProductWithBloomGuard(
  redis: Redis,
  productId: string,
  querySqlById: (id: string) => Promise<ProductRecord | null>,
): Promise<ProductRecord | null> {
  // Lớp 1: Hỏi bộ lọc Bloom trong 0.1ms. Nếu trả về 0 -> Chắc chắn 100% ID rác!
  const maybeExists = (await redis.call("BF.EXISTS", BLOOM_KEY, productId)) as number;
  if (maybeExists === 0) {
    return null; // Chặn đứng hoàn toàn trước khi tạo tải lên Redis String & SQL!
  }

  // Lớp 2: Tra cứu khóa Cache thông thường
  const cacheKey = `catalog:prod:${productId}`;
  const cached = await redis.get(cacheKey);
  if (cached === NULL_MARKER) return null;
  if (cached !== null) return JSON.parse(cached) as ProductRecord;

  // Lớp 3: ~0.5% False Positive của Bloom Filter lọt xuống SQL -> Ghi lại Null Sentinel 45s
  const row = await querySqlById(productId);
  if (!row) {
    await redis.set(cacheKey, NULL_MARKER, "EX", 45);
    return null;
  }

  await redis.set(cacheKey, JSON.stringify(row), "EX", 1800 + Math.floor(Math.random() * 300));
  return row;
}

caching/bad-stampede-naive-cache.ts:
// ============================================================================
// [ANTI-PATTERN / BUGGY] Ba Lỗi Cache Ngây Thơ Đánh Sập Cơ Sở Dữ Liệu Giờ Cao Điểm
// Hậu quả: Vừa dính Cache Stampede, vừa dính Penetration, vừa dính Avalanche!
// ============================================================================

import Redis from "ioredis";

export async function getCampaignBannerNaiveBuggy(
  redis: Redis,
  campaignId: string,
  queryHeavySql: (id: string) => Promise<Record<string, unknown> | null>,
): Promise<Record<string, unknown> | null> {
  const key = `campaign:banner:${campaignId}`;
  const raw = await redis.get(key);
  if (raw) {
    return JSON.parse(raw) as Record<string, unknown>;
  }

  // LỖI 1 (Cache Stampede): Không có Singleflight hay Mutex Lock!
  // Khi khóa banner trang chủ hết hạn đúng 12:00:00, 15,000 request đồng thời cùng thấy null
  // và cả 15,000 request lao thẳng xuống chạy câu lệnh JOIN nặng trong PostgreSQL!
  const record = await queryHeavySql(campaignId);

  // LỖI 2 (Cache Penetration): Nếu kẻ tấn công truyền campaignId = "-99999" không tồn tại,
  // hàm trả về null ngay mà không lưu Null Sentinel hay kiểm tra Bloom Filter -> SQL chịu trận 100%!
  if (!record) {
    return null;
  }

  // LỖI 3 (Cache Avalanche): Cố định cứng TTL = 3600s cho toàn bộ danh mục nạp cùng lúc,
  // khiến hàng vạn khóa đồng loạt hết hạn ở cùng một giây tròn giờ tiếp theo!
  await redis.set(key, JSON.stringify(record), "EX", 3600);
  return record;
}
